export type ManagementApiOperationId = keyof typeof MANAGEMENT_API_OPERATIONS
export type ManagementApiMethod =
  (typeof MANAGEMENT_API_OPERATIONS)[ManagementApiOperationId]['method']

type PathParameterNames<Path extends string> =
  Path extends `${string}{${infer Parameter}}${infer Rest}`
    ? Parameter | PathParameterNames<Rest>
    : never

export type ManagementApiPathParameters<OperationId extends ManagementApiOperationId> = [
  PathParameterNames<(typeof MANAGEMENT_API_OPERATIONS)[OperationId]['path']>,
] extends [never]
  ? never
  : Record<
      PathParameterNames<(typeof MANAGEMENT_API_OPERATIONS)[OperationId]['path']>,
      string | number
    >

type ManagementApiPathArguments<OperationId extends ManagementApiOperationId> = [
  ManagementApiPathParameters<OperationId>,
] extends [never]
  ? []
  : [parameters: ManagementApiPathParameters<OperationId>]

export function managementApiPath<OperationId extends ManagementApiOperationId>(
  operationId: OperationId,
  ...args: ManagementApiPathArguments<OperationId>
): string {
  const template = MANAGEMENT_API_OPERATIONS[operationId].path
  const parameters = args[0] as Record<string, string | number> | undefined
  return template.replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (_, name: string) => {
    const value = parameters?.[name]
    if (value === undefined || value === null || String(value).length === 0) {
      throw new TypeError(`Missing Management API path parameter: ${name}.`)
    }
    return encodeURIComponent(String(value))
  })
}


